const $=id=>document.getElementById(id),KEY='cs-midterm-v1',EXPOSURE='cs-midterm-exposure-v2';let state=null,section='mc',onlyMissed=false,tick;
function correct(q,a){const i=QUESTIONS.indexOf(q);return isEquivalent(q,a)||(q.kind==='fill'&&i>=0&&!!state?.overrides?.[i]);}
function answered(i){return state.answers[i]!=null&&String(state.answers[i]).trim()!=='';}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}}
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));if(!x||!Array.isArray(x.answers)||!Array.isArray(x.flags)||x.answers.length!==50||x.flags.length!==50)return null;
 if(x.version===1){x.version=2;x.questions=LEGACY_QUESTIONS.map((q,i)=>({...q,...BANK.find(b=>b.id==='seed-'+i+'-'+q.kind)}));x.overrides={};}
 return x.version===2&&x.questions?.length===50&&x.questions.every(q=>q.kind==='mc'?Array.isArray(q.options)&&Number.isInteger(q.correct)&&q.correct>=0&&q.correct<q.options.length:Array.isArray(q.accepted))?x:null;}catch{return null;}}
function exposure(){try{return JSON.parse(localStorage.getItem(EXPOSURE))||{};}catch{return {};}}
function freshQuestions(){const seen=exposure(),q=drawExam(BANK,seen);q.forEach(x=>seen[x.group]=(seen[x.group]||0)+1);try{localStorage.setItem(EXPOSURE,JSON.stringify(seen));}catch{}return q;}
function updateProgress(){const n=QUESTIONS.filter((_,i)=>answered(i)).length;$('progressText').textContent=`${n} / 50 answered`;$('progress').value=n;document.querySelectorAll('#map button').forEach((b,i)=>{b.classList.toggle('answered',answered(i));b.classList.toggle('flagged',!!state.flags[i]);});}
function map(){ $('map').replaceChildren();QUESTIONS.forEach((q,i)=>{const b=document.createElement('button');b.textContent=i+1;b.title=`Question ${i+1}`;b.onclick=()=>{section=q.kind;onlyMissed=false;render();if(state.submitted)result();$('q'+i).scrollIntoView({behavior:'smooth'});};$('map').append(b);});}
function render(){ $('questions').replaceChildren();$('tabMC').classList.toggle('active',section==='mc');$('tabFill').classList.toggle('active',section==='fill');QUESTIONS.forEach((q,i)=>{if(q.kind!==section||(onlyMissed&&correct(q,state.answers[i])))return;const a=document.createElement('article');a.id='q'+i;const top=document.createElement('div');top.className='qtop';top.textContent=`QUESTION ${String(i+1).padStart(2,'0')} / 2 POINTS`;const flag=document.createElement('button');flag.className='flag'+(state.flags[i]?' on':'');flag.textContent=state.flags[i]?'Flagged':'Flag for review';flag.setAttribute('aria-pressed',!!state.flags[i]);flag.onclick=()=>{state.flags[i]=!state.flags[i];save();render();};top.append(flag);a.append(top);const h=document.createElement('h2');h.id='label'+i;h.textContent=q.prompt;a.append(h);if(q.kind==='mc'){const opts=document.createElement('div');opts.className='options';opts.setAttribute('role','radiogroup');opts.setAttribute('aria-labelledby',h.id);q.options.forEach((o,j)=>{const label=document.createElement('label');label.className='option';const r=document.createElement('input');r.type='radio';r.name='q'+i;r.value=j;r.checked=state.answers[i]===j;r.disabled=state.submitted;r.onchange=()=>{state.answers[i]=j;save();updateProgress();};label.append(r,document.createTextNode(o));opts.append(label);});a.append(opts);}else{const input=document.createElement('input');input.type='text';input.autocomplete='off';input.spellcheck=false;input.setAttribute('aria-labelledby',h.id);input.placeholder='Type your answer…';input.value=state.answers[i]??'';input.disabled=state.submitted;input.oninput=()=>{state.answers[i]=input.value;save();updateProgress();};a.append(input);}if(state.submitted){const ok=correct(q,state.answers[i]),v=document.createElement('div');v.className='review'+(ok?'':' wrong');const b=document.createElement('b');b.textContent=ok?'Correct · 2 / 2':'Not yet · 0 / 2';const p=document.createElement('div');p.textContent='Textbook answer: '+q.answer;const small=document.createElement('small');small.textContent=q.source;v.append(b,p,small);if(q.kind==='fill'&&answered(i)&&!isEquivalent(q,state.answers[i])){const label=document.createElement('label');label.className='self-assess';const check=document.createElement('input');check.type='checkbox';check.checked=!!state.overrides?.[i];check.onchange=()=>{state.overrides??={};state.overrides[i]=check.checked;save();render();result();};label.append(check,document.createTextNode(' My wording is equivalent — count as correct (self-assessed)'));v.append(label);}if(state.overrides?.[i])b.textContent='Correct · 2 / 2 · self-assessed';a.append(v);} $('questions').append(a);});updateProgress();$('sectionNote').textContent=section==='mc'?'Part 1 · 20 questions · 40 points':'Part 2 · 30 questions · 60 points';$('nextSection').textContent=section==='mc'?'Next: Fill in the blank →':'← Back to multiple choice';$('submit').hidden=state.submitted;}
function result(){let mc=0,fill=0;QUESTIONS.forEach((q,i)=>{if(correct(q,state.answers[i]))q.kind==='mc'?mc++:fill++;});$('result').hidden=false;$('result').innerHTML='';const box=document.createElement('div');box.className='result-card';const h=document.createElement('h2');h.textContent=`${(mc+fill)*2} / 100`;const p=document.createElement('p');p.textContent=`Multiple choice: ${mc}/20 · Fill in the blank: ${fill}/30`;const note=document.createElement('p');note.className='fine';note.textContent='Equivalent terms, abbreviations, English–Mandarin combinations, and common number formats are accepted. An unfamiliar paraphrase may need review: use the self-assessment checkbox only if its meaning matches the textbook. Self-assessed points are included in your score. No partial credit.';const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=onlyMissed;check.onchange=()=>{onlyMissed=check.checked;render();};label.append(check,document.createTextNode(' Show only missed questions'));box.append(h,p,note,label);$('result').append(box);$('modeLabel').textContent='YOUR RESULTS';$('examTitle').textContent='Every mistake is a clue.';}
function timer(){clearInterval(tick);function update(){if(state.submitted){$('clockLabel').textContent='EXAM COMPLETE';$('clock').textContent='Review';return;}if(!state.deadline){$('clock').textContent='Untimed';return;}const seconds=Math.max(0,Math.ceil((state.deadline-Date.now())/1000));$('clock').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');document.querySelector('.clock').classList.toggle('warning',seconds<300);if(!seconds){finish();}}update();if(!state.submitted)tick=setInterval(update,1000);}
function enter(){ QUESTIONS=state.questions;section='mc';onlyMissed=false;$('clockLabel').textContent='TIME REMAINING';document.querySelector('.clock').classList.remove('warning');$('intro').hidden=true;$('workspace').hidden=false;$('result').hidden=!state.submitted;$('modeLabel').textContent='YOUR REHEARSAL';$('examTitle').textContent='Make it count.';map();render();if(state.submitted)result();timer();}
function finish(){if(state.submitted)return;state.submitted=true;state.finishedAt=Date.now();save();$('confirm').close();render();result();timer();window.scrollTo({top:0,behavior:'smooth'});}
$('start').onclick=()=>{if(load()&&!window.confirm('Replace your saved attempt and start again?'))return;const minutes=Number($('duration').value);state={version:2,questions:freshQuestions(),answers:Array(50).fill(null),flags:Array(50).fill(false),overrides:{},deadline:minutes?Date.now()+minutes*60000:null,submitted:false};save();enter();};
$('resume').hidden=!load();$('resume').onclick=()=>{state=load();if(state)enter();};
$('tabMC').onclick=()=>{section='mc';render();};$('tabFill').onclick=()=>{section='fill';render();};$('nextSection').onclick=()=>{section=section==='mc'?'fill':'mc';render();document.querySelector('.tabs').scrollIntoView({behavior:'smooth'});};
$('submit').onclick=()=>{const left=QUESTIONS.filter((_,i)=>!answered(i)).length;$('confirmText').textContent=left?`You have ${left} unanswered question${left===1?'':'s'}. Blank answers receive zero points. Submit and reveal the answer key?`:'All 50 questions are answered. Submit and reveal your score and textbook sources?';$('confirm').showModal();};$('cancelSubmit').onclick=()=>$('confirm').close();$('confirmSubmit').onclick=finish;
$('newAttempt').onclick=()=>{if(!window.confirm('Start over? Your saved attempt will be replaced when you start the new exam.'))return;clearInterval(tick);$('workspace').hidden=true;$('intro').hidden=false;$('resume').hidden=!load();window.scrollTo({top:0});};

$('bankInfo').textContent=`${BANK.length} questions in the bank · Textbook + Chapters 1–8 homework`;
